import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { getToken, getUser, logout } from "../utils/auth";

export default function Navbar() {
  const nav = useNavigate();
  const token = getToken();
  const user = getUser();

  return (
    <div className="w-full border-b bg-white">
      <div className="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between">
        <Link to="/" className="font-extrabold text-xl tracking-tight">
          🛡️ CyberRaksha
          <div className="text-xs font-medium text-gray-500">
            Scam se Suraksha. Digital Raksha.
          </div>
        </Link>

        <div className="flex gap-4 items-center text-sm">
          <Link className="hover:underline" to="/report">
            Scam Check
          </Link>
          <Link className="hover:underline" to="/pricing">
            Pricing
          </Link>
          <Link className="hover:underline" to="/emergency">
            Emergency
          </Link>

          {/* USER */}
          {token && user?.role === "USER" && (
            <Link className="hover:underline" to="/my">
              My Cases
            </Link>
          )}

          {/* AUTH BUTTONS */}
          {token ? (
            <button
              className="px-3 py-2 rounded-xl bg-gray-900 text-white"
              onClick={() => {
                logout();
                nav("/");
              }}
            >
              Logout
            </button>
          ) : (
            <div className="flex gap-2">
              <Link
                className="px-3 py-2 rounded-xl border"
                to="/login"
              >
                User Login
              </Link>

              <Link
                className="px-3 py-2 rounded-xl bg-gray-900 text-white"
                to="/admin/login"
              >
                Admin
              </Link>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
